main() {
    loop {
        {{function}}()
    }
}

function {{function}}() {
    if ({{sensor}}.scan() != null) {
        if ({{sensor}}.scan().Distance < 2.5) {
            if ({{sensor}}.scan().Angle() < 10) {
                move(90, 1)
            } else {
                if ({{sensor}}.scan().Angle() > 350) {
                    move(90, 1)
                } else {
                    move(0, 0)
                }
            }
        } else {
            move(0, 0)
        }
    } else {
        move(0, 0)
    }
}
